package pl.atrop.powerguard.bcknd.shared.infrastructure.repository.db.sqldb.boundaries;
import jakarta.enterprise.context.ApplicationScoped; import jakarta.persistence.*; import java.util.*; import pl.atrop.powerguard.bcknd.shared.infrastructure.repository.db.sqldb.entities.Meters;
@ApplicationScoped public class MetersBoundary extends AbstractFacade<Meters>{ @PersistenceContext(unitName="powerguradPU") private EntityManager em; public MetersBoundary(){super(Meters.class);} protected EntityManager getEntityManager(){return em;}
 public Optional<Meters> findByEdgeFkAndUniqueKey(Long edgeFk,String key){return em.createQuery("SELECT m FROM Meters m WHERE m.edgeFk=:e AND m.uniqueKey=:k",Meters.class).setParameter("e",edgeFk).setParameter("k",key).setMaxResults(1).getResultStream().findFirst();}
 public boolean uniqueKeyExistsForOtherMeter(Long edgeFk,String key,Integer id){String q=id==null?"SELECT COUNT(m) FROM Meters m WHERE m.edgeFk=:e AND m.uniqueKey=:k":"SELECT COUNT(m) FROM Meters m WHERE m.edgeFk=:e AND m.uniqueKey=:k AND m.id<>:id";var x=em.createQuery(q,Long.class).setParameter("e",edgeFk).setParameter("k",key);if(id!=null)x.setParameter("id",id);return x.getSingleResult()>0;}
 public List<Meters> findAllOrdered(){return em.createQuery("SELECT m FROM Meters m ORDER BY m.edgeFk,m.displayOrder,m.id",Meters.class).getResultList();} public int nextDisplayOrder(Long edgeFk){Integer max=em.createQuery("SELECT MAX(m.displayOrder) FROM Meters m WHERE m.edgeFk=:e",Integer.class).setParameter("e",edgeFk).getSingleResult();return(max==null?0:max)+1;} public Meters save(Meters m){if(m.getId()==null){em.persist(m);em.flush();return m;}Meters r=em.merge(m);em.flush();return r;} public void deleteById(Integer id){Meters m=find(id);if(m!=null){remove(m);em.flush();}}
}
